function finalPrices(prices: number[]): number[] {
  const res = prices.slice(), stack: number[] = [];
  for (let i = 0; i < prices.length; i++) {
    while (stack.length && prices[stack[stack.length - 1]] >= prices[i]) {
      res[stack.pop()!] -= prices[i];
    }
    stack.push(i);
  }
  return res;
}

